  ],
  "claims": [
    {
      "claim": "Closest context 17-BMP: absolute oral bioavailability 41% (90% CI 31–54%) after oral BDP, with additional estimates ~40%, 26%, and 21%; all are at or above the 20% threshold.",
      "card_ids": ["C11", "C23", "C08", "C26", "C09"]
    },
    {
      "claim": "Related 6-chloro steroids chlormadinone acetate (~100%) and cyproterone acetate (88%) show high oral bioavailability, supporting favorable absorption for the halogenated steroid scaffold.",
      "card_ids": ["C15", "C20", "C37", "C36"]
    },
    {
      "claim": "Prednisolone/prednisone absorption is near-complete: fraction absorbed 95%, >98% urinary recovery after oral dosing, complete absorption, high human Peff, and >99% jejunal absorption.",
      "card_ids": ["C63", "C56", "C55", "C53", "C60"]
    },
    {
      "claim": "Prednisolone is a P-gp/CYP3A4 substrate with measurable efflux (ER 2.13 in rat jejunum), but the same record family notes human absolute oral bioavailability of prednisolone is ~70%, so efflux does not preclude F≥20%.",
      "card_ids": ["C67", "C70", "C72", "C74"]
    },
    {
      "claim": "Hydrocortisone has high intestinal permeability dominated by passive diffusion, and P-gp-inhibiting surfactants increase prednisolone absorption; these are mechanistic observations, not direct query F results.",
      "card_ids": ["C66", "C69", "C73", "C75"]
    },
    {
      "claim": "No visible record provides affirmative threshold-relevant evidence for F <20% in the query or its closest context; the lowest BMP estimate (21%) remains above threshold.",
      "card_ids": ["C09", "C26"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C64", "C65", "C66", "C67", "C68", "C69", "C70", "C71", "C72", "C73", "C74", "C75"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query; closest evidence is for 17-BMP, which differs by 17-propionate, 16-methyl, and 9-chloro versus 6-chloro-1,4,6-triene.",
    "L5 efflux/metabolism records are for prednisolone and hydrocortisone, not the query; no query-specific P-gp or CYP3A4 data.",
    "No quantitative intestinal extraction or first-pass loss for the query; P-gp efflux and CYP3A4 metabolism are mechanistic only.",
    "Some BMP estimates (21%, 26%) are close to the 20% threshold, leaving margin uncertainty.",
    "No query-specific formulation or fed/fasted data."
  ],
  "decision_summary": "Predicted high (F >= 20%) because the closest structural context 17-BMP shows absolute oral bioavailability of 41% (90% CI 31–54%) with additional estimates of 40%, 26%, and 21%, all at or above threshold; related 6-chloro steroids chlormadinone acetate and cyproterone acetate show high oral bioavailability; L4 absorption/permeability records for prednisolone/prednisone show near-complete absorption and high permeability; L5 P-gp efflux records for prednisolone are mechanistic and do not overturn this because prednisolone has ~70% oral bioavailability despite being a P-gp substrate. No affirmative evidence supports F <20%."
}

